// Documinder core — deterministic credential classification (Phase 1).
//
// Pure functions with no dependencies, so the same code runs in three places:
//   1. Node unit tests (tests/core.test.mjs)
//   2. The n8n "Classify credentials" Code node (see workflows/)
//   3. Anyone reading the repo who wants to understand the rules
//
// No LLM is involved. Dates are compared as calendar days, never as timestamps.

const MS_PER_DAY = 86400000;

const ENDORSEMENT_TYPES = ['HAZMAT_ENDORSEMENT', 'TANKER_ENDORSEMENT', 'DOUBLES_TRIPLES_ENDORSEMENT'];
const DEFAULT_STAGES = [90, 60, 30, 14, 7, 0];

// ---------- Dates ----------

// Parses a strict YYYY-MM-DD string into a whole-day number (days since 1970-01-01).
// Rejects malformed strings and impossible dates such as 2026-02-30.
function parseCalendarDate(value) {
  if (value === null || value === undefined || String(value).trim() === '') {
    return { ok: false, reason: 'blank' };
  }
  const s = String(value).trim();
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
  if (!m) return { ok: false, reason: `malformed date "${s}" (expected YYYY-MM-DD)` };
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])];
  const ms = Date.UTC(y, mo - 1, d);
  const check = new Date(ms);
  if (check.getUTCFullYear() !== y || check.getUTCMonth() !== mo - 1 || check.getUTCDate() !== d) {
    return { ok: false, reason: `impossible calendar date "${s}"` };
  }
  return { ok: true, day: Math.round(ms / MS_PER_DAY), iso: s };
}

// Today's calendar date (YYYY-MM-DD) in the business timezone.
function todayInTimezone(timeZone, now = new Date()) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(now);
  const get = (t) => parts.find((p) => p.type === t).value;
  return `${get('year')}-${get('month')}-${get('day')}`;
}

// The fixed test date wins when set; otherwise use the real date in the business timezone.
function resolveReferenceDate(settings, now = new Date()) {
  const tz = settings.business_timezone || 'America/Los_Angeles';
  const fixed = settings.test_reference_date;
  if (fixed !== null && fixed !== undefined && String(fixed).trim() !== '') {
    const parsed = parseCalendarDate(fixed);
    if (!parsed.ok) throw new Error(`Settings.test_reference_date is invalid: ${parsed.reason}`);
    return { iso: parsed.iso, day: parsed.day, source: 'test_reference_date', timeZone: tz };
  }
  const iso = todayInTimezone(tz, now);
  return { iso, day: parseCalendarDate(iso).day, source: 'current_date', timeZone: tz };
}

// ---------- Policy ----------

function parseStages(value) {
  if (value === null || value === undefined || String(value).trim() === '') return DEFAULT_STAGES.slice();
  const stages = String(value)
    .split(',')
    .map((s) => Number(s.trim()))
    .filter((n) => Number.isInteger(n) && n >= 0);
  return [...new Set(stages)].sort((a, b) => b - a);
}

// State is defined by the reminder policy table in the build brief.
function stateForDays(days) {
  if (days < 0) return 'overdue';
  if (days === 0) return 'expires_today';
  if (days <= 7) return 'critical';
  if (days <= 30) return 'urgent';
  if (days <= 90) return 'approaching_expiry';
  return 'current';
}

// Only the *current* applicable stage is returned; missed earlier stages are never replayed.
// Example with stages 90,60,30,14,7,0: 45 days left -> D60, 90 -> D90, 91 -> none.
function stageForDays(days, stages) {
  if (days < 0) return 'OVERDUE';
  const due = stages.filter((s) => s >= days);
  if (due.length === 0) return '';
  return `D${Math.min(...due)}`;
}

function actionFor(state, escalationPolicy) {
  const escalates = escalationPolicy !== 'none';
  switch (state) {
    case 'approaching_expiry':
    case 'urgent':
    case 'critical':
      return 'driver_reminder';
    case 'expires_today':
      return escalates ? 'driver_notice_and_staff_escalation' : 'driver_notice';
    case 'overdue':
      return escalates ? 'staff_escalation' : 'none';
    case 'missing':
    case 'invalid_date':
      return 'staff_review';
    default:
      return 'none';
  }
}

// ---------- Documents ----------

function isTrue(v) {
  return v === true || v === 'true' || v === 'TRUE' || v === 1 || v === '1';
}

// Latest verified version of one document type for one driver (archived/pending rows ignored).
function latestVerified(documents, driverId, documentType) {
  return documents
    .filter((d) => d.driver_id === driverId && d.document_type === documentType && d.status === 'verified')
    .sort((a, b) => Number(b.version) - Number(a.version))[0];
}

// ---------- Classification ----------

function classifyAll({ settings, drivers, requirements, documents, now = new Date() }) {
  const ref = resolveReferenceDate(settings, now);
  const rows = [];

  for (const driver of drivers) {
    const active = isTrue(driver.active);
    const reqs = requirements.filter((r) => r.applicable_role === driver.role);

    if (reqs.length === 0) {
      rows.push(baseRow(ref, driver, { document_type: '*' }, {
        state: 'invalid_date',
        action: 'staff_review',
        reason: `no requirements configured for role "${driver.role}"`,
      }));
      continue;
    }

    for (const req of reqs) {
      if (!active) {
        rows.push(baseRow(ref, driver, req, { state: 'inactive_skipped', reason: 'driver is inactive' }));
        continue;
      }
      if (!isTrue(req.required)) {
        rows.push(baseRow(ref, driver, req, { state: 'not_applicable', reason: `not required for role ${driver.role}` }));
        continue;
      }

      const doc = latestVerified(documents, driver.driver_id, req.document_type);
      if (!doc) {
        rows.push(baseRow(ref, driver, req, {
          state: 'missing',
          action: actionFor('missing'),
          reason: 'required document has no verified version on file',
        }));
        continue;
      }

      // Endorsements may share the CDL expiration date. Never invent a date:
      // inherit only when the endorsement record is blank and a verified CDL exists.
      let expirationRaw = doc.expiration_date;
      let expirationSource = 'document';
      if ((expirationRaw === null || expirationRaw === undefined || String(expirationRaw).trim() === '') &&
          ENDORSEMENT_TYPES.includes(req.document_type)) {
        const cdl = latestVerified(documents, driver.driver_id, 'CDL');
        if (cdl) {
          expirationRaw = cdl.expiration_date;
          expirationSource = `inherited_from_cdl:${cdl.document_id}`;
        }
      }

      const exp = parseCalendarDate(expirationRaw);
      const docFields = {
        document_id: doc.document_id,
        document_version: Number(doc.version),
        expiration_date: expirationRaw === null || expirationRaw === undefined ? '' : String(expirationRaw),
        expiration_source: expirationSource,
      };

      if (!exp.ok) {
        rows.push(baseRow(ref, driver, req, {
          ...docFields,
          state: 'invalid_date',
          action: actionFor('invalid_date'),
          reason: exp.reason === 'blank' ? 'expiration date not provided' : exp.reason,
        }));
        continue;
      }

      const issue = parseCalendarDate(doc.issue_date);
      if (issue.ok && issue.day > exp.day) {
        rows.push(baseRow(ref, driver, req, {
          ...docFields,
          state: 'invalid_date',
          action: actionFor('invalid_date'),
          reason: `issue_date ${issue.iso} is after expiration_date ${exp.iso}`,
        }));
        continue;
      }

      const days = exp.day - ref.day;
      const state = stateForDays(days);
      const stage = state === 'current' ? '' : stageForDays(days, parseStages(req.reminder_stages));
      rows.push(baseRow(ref, driver, req, {
        ...docFields,
        days_remaining: days,
        state,
        reminder_stage: stage,
        action: actionFor(state, req.escalation_policy),
        reason: `${days} day(s) remaining as of ${ref.iso} (${ref.timeZone})`,
      }));
    }
  }
  return { reference: ref, rows };
}

function baseRow(ref, driver, req, fields) {
  return {
    reference_date: ref.iso,
    reference_source: ref.source,
    driver_id: driver.driver_id,
    full_name: driver.full_name,
    role: driver.role,
    active: isTrue(driver.active),
    requirement_id: req.requirement_id || '',
    document_type: req.document_type,
    document_id: '',
    document_version: null,
    expiration_date: '',
    expiration_source: '',
    days_remaining: null,
    state: '',
    reminder_stage: '',
    action: 'none',
    reason: '',
    // Phase 2 dedup key: driver_id + document_id + document_version + reminder_stage
    dedup_key: '',
    ...fields,
  };
}

function withDedupKeys(rows) {
  return rows.map((r) => ({
    ...r,
    dedup_key: r.reminder_stage && r.document_id
      ? `${r.driver_id}|${r.document_id}|${r.document_version}|${r.reminder_stage}`
      : '',
  }));
}

// Compares actual rows with expected rows keyed by driver_id + document_type.
function compareWithExpected(rows, expected) {
  const actualByKey = new Map(rows.map((r) => [`${r.driver_id}:${r.document_type}`, r]));
  const results = expected.map((e) => {
    const a = actualByKey.get(`${e.driver_id}:${e.document_type}`);
    const actualState = a ? a.state : '(no row)';
    const actualStage = a ? a.reminder_stage : '';
    const pass = actualState === e.expected_state && (actualStage || '') === (e.expected_stage || '');
    return {
      driver_id: e.driver_id,
      full_name: a ? a.full_name : '',
      document_type: e.document_type,
      primary_fixture: isTrue(e.primary_fixture),
      expected_state: e.expected_state,
      actual_state: actualState,
      expected_stage: e.expected_stage || '',
      actual_stage: actualStage || '',
      days_remaining: a ? a.days_remaining : null,
      pass,
    };
  });
  const expectedKeys = new Set(expected.map((e) => `${e.driver_id}:${e.document_type}`));
  const unexpected = rows.filter((r) => !expectedKeys.has(`${r.driver_id}:${r.document_type}`));
  const failed = results.filter((r) => !r.pass).length + unexpected.length;
  return { results, unexpected, total: results.length, passed: results.length - results.filter((r) => !r.pass).length, failed };
}

function summarize(rows) {
  const counts = {};
  for (const r of rows) counts[r.state] = (counts[r.state] || 0) + 1;
  return counts;
}

// Documinder renewals — Phase 4: renewal intake and review (Workflow B).
// Deterministic, no LLM. Uses parseCalendarDate / resolveReferenceDate / latestVerified
// from documinder-core.js (in n8n the two files are concatenated into one Code node).
//
// History is never destroyed: approval archives the old version and adds a new one;
// rejection leaves every document row untouched.



const isTrueValue = (v) => v === true || v === 'true' || v === 1 || v === '1';
const clean = (v) => (v === null || v === undefined ? '' : String(v).trim());

// ---------- Intake ----------

// Decides what to do with one renewal submission:
//   pending_review    -> store it for a reviewer
//   invalid_submission-> store it with the reason (audit trail), nothing to review
//   duplicate         -> an open submission already exists; return it, store nothing
function evaluateSubmission({ submission, settings, drivers, requirements, documents, renewals, now = new Date(), renewalId }) {
  const driverId = clean(submission.driver_id).toUpperCase();
  const documentType = clean(submission.document_type).toUpperCase();
  const expRaw = clean(submission.submitted_expiration_date);
  const fileUrl = clean(submission.submitted_file_url);
  const ref = resolveReferenceDate(settings, now);

  const base = {
    renewal_id: renewalId,
    driver_id: driverId,
    document_type: documentType,
    submitted_expiration_date: expRaw,
    submitted_file_url: fileUrl,
    submitted_at: now.toISOString(),
    reviewed_at: '',
    reviewed_by: '',
    rejection_reason: '',
    previous_document_id: '',
    previous_version: null,
    previous_expiration_date: '',
    new_document_id: '',
    new_version: null,
  };

  const open = renewals.find((r) => r.driver_id === driverId && r.document_type === documentType && r.status === 'pending_review');
  if (open) {
    return { outcome: 'duplicate', store: false, renewal: open, message: `Renewal ${open.renewal_id} is already waiting for review; no new submission created.` };
  }

  const problems = [];
  const driver = drivers.find((d) => d.driver_id === driverId);
  if (!driver) problems.push(`unknown driver "${driverId}"`);
  else if (!isTrueValue(driver.active)) problems.push(`driver ${driverId} is inactive`);

  if (driver) {
    const req = requirements.find((r) => r.applicable_role === driver.role && r.document_type === documentType);
    if (!req) problems.push(`${documentType} is not a tracked document type for role ${driver.role}`);
    else if (!isTrueValue(req.required)) problems.push(`${documentType} is not required for role ${driver.role}`);
  }

  const exp = parseCalendarDate(expRaw);
  if (!exp.ok) problems.push(exp.reason === 'blank' ? 'expiration date is missing' : exp.reason);
  else if (exp.day <= ref.day) problems.push(`expiration ${exp.iso} is not after today (${ref.iso})`);

  const current = driver ? latestVerified(documents, driverId, documentType) : undefined;
  if (exp.ok && current) {
    const cur = parseCalendarDate(current.expiration_date);
    if (cur.ok && exp.day <= cur.day) problems.push(`expiration ${exp.iso} does not extend the current verified date ${cur.iso}`);
  }

  if (!/^https?:\/\/\S+$/i.test(fileUrl)) problems.push('a link to the renewed document (http/https) is required');

  if (problems.length) {
    return {
      outcome: 'invalid_submission',
      store: true,
      renewal: { ...base, status: 'invalid_submission', rejection_reason: problems.join('; ') },
      message: `Submission not accepted: ${problems.join('; ')}.`,
    };
  }
  return {
    outcome: 'pending_review',
    store: true,
    renewal: {
      ...base,
      status: 'pending_review',
      previous_document_id: current ? current.document_id : '',
      previous_version: current ? Number(current.version) : null,
      previous_expiration_date: current ? clean(current.expiration_date) : '',
    },
    message: `Renewal ${renewalId} received and waiting for compliance review. The verified record is unchanged until it is approved.`,
  };
}

// ---------- Review ----------

// Decides one review. Returns a plan the workflow executes:
//   refuse  -> nothing changes (not found, already reviewed, unauthorized, missing reason)
//   reject  -> renewal row updated only
//   approve -> archive old version, insert new verified version, update renewal,
//              close old-version notifications, resolve related staff-review items
function evaluateReview({ review, settings, reviewers, renewals, documents, notifications, staffReview, now = new Date() }) {
  const renewalId = clean(review.renewal_id).toUpperCase();
  const reviewerEmail = clean(review.reviewer_email).toLowerCase();
  const decision = clean(review.decision).toLowerCase();
  const reason = clean(review.rejection_reason);
  const refuse = (message) => ({ action: 'refuse', message, renewal_id: renewalId });

  const renewal = renewals.find((r) => clean(r.renewal_id).toUpperCase() === renewalId);
  if (!renewal) return refuse(`Renewal ${renewalId} was not found.`);
  if (renewal.status !== 'pending_review') {
    return refuse(`Renewal ${renewalId} is ${renewal.status}${renewal.reviewed_by ? ` (by ${renewal.reviewed_by})` : ''}; it can only be reviewed once.`);
  }
  const reviewer = reviewers.find((r) => clean(r.reviewer_email).toLowerCase() === reviewerEmail && isTrueValue(r.active));
  if (!reviewer) return refuse(`${reviewerEmail || 'This reviewer'} is not an authorized reviewer.`);
  if (decision !== 'approve' && decision !== 'reject') return refuse('Decision must be approve or reject.');

  const reviewedAt = now.toISOString();
  if (decision === 'reject') {
    if (!reason) return refuse('A rejection needs a reason so the driver knows what to fix.');
    return {
      action: 'reject',
      renewal_id: renewalId,
      renewal_update: { status: 'rejected', reviewed_at: reviewedAt, reviewed_by: reviewerEmail, rejection_reason: reason },
      message: `Renewal ${renewalId} rejected: ${reason.replace(/[.\s]+$/, '')}. The verified document was not changed.`,
    };
  }

  // Approve: re-check against the documents as they are now, not as they were at submission.
  const exp = parseCalendarDate(renewal.submitted_expiration_date);
  if (!exp.ok) return refuse(`Submitted expiration date is invalid: ${exp.reason}.`);
  const current = latestVerified(documents, renewal.driver_id, renewal.document_type);
  if (current) {
    const cur = parseCalendarDate(current.expiration_date);
    if (cur.ok && exp.day <= cur.day) return refuse(`Submitted date ${exp.iso} no longer extends the verified date ${cur.iso}.`);
  }
  const versions = documents
    .filter((d) => d.driver_id === renewal.driver_id && d.document_type === renewal.document_type)
    .map((d) => Number(d.version) || 0);
  const newVersion = (versions.length ? Math.max(...versions) : 0) + 1;
  const documentId = current ? current.document_id : `DOC-${renewalId}`;
  const ref = resolveReferenceDate(settings, now);

  const newDocument = {
    document_id: documentId,
    driver_id: renewal.driver_id,
    document_type: renewal.document_type,
    version: newVersion,
    issue_date: ref.iso,
    expiration_date: exp.iso,
    status: 'verified',
    source_file_url: renewal.submitted_file_url,
    verified_at: reviewedAt,
    verified_by: reviewerEmail,
  };

  const closedReason = `superseded by renewal ${renewalId} (v${newVersion})`;
  const notificationsToClose = current
    ? notifications
        .filter((n) => n.document_id === current.document_id && Number(n.document_version) === Number(current.version) && !clean(n.closed_at))
        .map((n) => ({ notification_id: n.notification_id, closed_at: reviewedAt, closed_reason: closedReason }))
    : [];
  const closedIds = new Set(notificationsToClose.map((n) => n.notification_id));
  const reviewItemsToResolve = staffReview
    .filter((s) => s.status === 'open' && (closedIds.has(s.notification_id) ||
      (s.driver_id === renewal.driver_id && s.document_type === renewal.document_type && (s.category === 'missing_document' || s.category === 'invalid_date'))))
    .map((s) => ({ review_key: s.review_key, status: 'resolved', resolved_at: reviewedAt, resolution: closedReason }));

  return {
    action: 'approve',
    renewal_id: renewalId,
    archive: current ? { document_id: current.document_id, version: Number(current.version) } : null,
    new_document: newDocument,
    renewal_update: {
      status: 'approved',
      reviewed_at: reviewedAt,
      reviewed_by: reviewerEmail,
      rejection_reason: '',
      new_document_id: documentId,
      new_version: newVersion,
    },
    notifications_to_close: notificationsToClose,
    review_items_to_resolve: reviewItemsToResolve,
    message: `Renewal ${renewalId} approved: ${renewal.document_type} for ${renewal.driver_id} is now v${newVersion}, expiring ${exp.iso}.` +
      (current ? ` v${current.version} archived; ${notificationsToClose.length} reminder(s) closed.` : ' First verified version on file.'),
  };
}

// ---------- n8n glue ----------
const form = $('Submit Renewal Form').first().json;
const submission = {
  driver_id: String(form.driver || '').split(' ')[0],
  document_type: form.document_type,
  submitted_expiration_date: form.submitted_expiration_date,
  submitted_file_url: form.submitted_file_url,
};
const result = evaluateSubmission({
  submission,
  settings: $('Load Settings (intake)').first().json,
  drivers: $('Load Drivers (intake)').all().map((i) => i.json),
  requirements: $('Load Requirements (intake)').all().map((i) => i.json),
  documents: $('Load Documents (intake)').all().map((i) => i.json),
  renewals: $('Load Renewals (intake)').all().map((i) => i.json).filter((r) => r.renewal_id),
  renewalId: 'RN-' + $execution.id,
});
return [{ json: { outcome: result.outcome, store: result.store, message: result.message, ...result.renewal } }];

// Documinder core — deterministic credential classification (Phase 1).
//
// Pure functions with no dependencies, so the same code runs in three places:
